using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Diagnostics;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace GlassBoard {
    public partial class Controller {
        WidgetManager widgets;

        public bool UiBusy{get{return settingsOpen||Board.ModalBusy;}}
        Window OwnerWindow{get{return Board.IsVisible?(Window)Board:Dock;}}
        public void RefreshWidgets(){RefreshControlCenter();if(widgets==null)widgets=new WidgetManager(this);widgets.Sync();}
        public void SetWidgetEnabled(string kind,bool value){if(widgets==null)widgets=new WidgetManager(this);widgets.Enable(kind,value);}
        public string WidgetStatus{get{return widgets==null?"":widgets.LastError;}}
        public void RecoverWidgets(){try{if(File.Exists(Store.FileName))File.Copy(Store.FileName,Store.FileName+".before-widget-recovery-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"),false);WidgetRules.Recover(Prefs.Widgets);Save();Store.Trace("RECOVER enable all widgets, preserve contents and layout");ReopenWidgets();}catch(Exception ex){Store.Log(ex);MessageBox.Show(ex.Message,"组件恢复失败");}}
        public void ReopenWidgets(){if(widgets==null)widgets=new WidgetManager(this);widgets.Reopen();if(!string.IsNullOrEmpty(widgets.LastError))MessageBox.Show(widgets.LastError+"\n详细记录位于配置文件夹 error.log。","组件打开失败");}
        public void CloseWidgets(){if(widgets!=null){widgets.Dispose();widgets=null;}}
        public void ConfigureWidgets(){Settings(3);}
        public void AddFolder(){bool previous=Board.ModalBusy;Board.ModalBusy=true;try{string folder=FeatureUi.PickFolder(OwnerWindow,"选择要放入玻璃板的文件夹（添加文件夹本身）");if(folder==null)return;Add(new[]{folder});Board.ClearSearch();Board.SetStatus("已添加文件夹入口 · 点击打开，右键可固定到 Dock");}finally{Board.ModalBusy=previous;}}

        public async void ToggleTaskbarAutoHide(bool? enabled=null){try{bool next=enabled??!TaskbarAutoHide.Enabled;if(next)DesktopVisibility.SetHidden(true,false);TaskbarAutoHide.Set(next);Board.SetStatus("已请求"+(next?"启用":"关闭")+" Windows 任务栏自动隐藏");await Task.Delay(250);if(Application.Current!=null&&!Application.Current.Dispatcher.HasShutdownStarted)Dock.Refresh();}catch(Exception ex){Store.Log(ex);MessageBox.Show(ex.Message,"Windows 任务栏自动隐藏");}}
        public void Customize(Entry entry){bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var w=FeatureUi.Dialog("名称与图标",OwnerWindow,500,280);var stack=new StackPanel{Margin=new Thickness(22)};w.Content=stack;stack.Children.Add(new TextBlock{Text="显示名称",Margin=new Thickness(0,0,0,8)});var name=new TextBox{Text=entry.Name,MinHeight=38};stack.Children.Add(name);string icon=entry.IconPath;var info=new TextBlock{Text=string.IsNullOrWhiteSpace(icon)?"使用软件原图标":"已使用自定义图标",Margin=new Thickness(0,12,0,12)};stack.Children.Add(info);
            var row=new WrapPanel();stack.Children.Add(row);row.Children.Add(FeatureUi.Button("选择图标",()=>{var pick=new Microsoft.Win32.OpenFileDialog{Filter="图标图片|*.png;*.ico;*.jpg;*.jpeg;*.bmp"};if(pick.ShowDialog(w)==true){try{icon=FeatureUi.StoreIcon(pick.FileName);info.Text="已选择图标，点击保存应用";}catch(Exception ex){MessageBox.Show(w,ex.Message,"无法读取图标");}}}));row.Children.Add(FeatureUi.Button("恢复原图标",()=>{icon=null;info.Text="使用软件原图标";}));stack.Children.Add(FeatureUi.Button("保存",()=>{if(string.IsNullOrWhiteSpace(name.Text))return;var before=BeginBoardEdit();entry.Name=name.Text.Trim();entry.IconPath=icon;EndBoardEdit(before,"自定义名称与图标");Refresh();w.Close();}));w.ShowDialog();
        }finally{Board.ModalBusy=previous;}}
        public void AddExistingToGroup(string group){if(group=="全部")return;bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var w=FeatureUi.Dialog("添加已有图标到「"+group+"」",Board,680,620);var root=new DockPanel{Margin=new Thickness(22)};w.Content=root;var header=new StackPanel();DockPanel.SetDock(header,System.Windows.Controls.Dock.Top);root.Children.Add(header);header.Children.Add(new TextBlock{Text="同一软件可以出现在多个分组",FontSize=18,Margin=new Thickness(0,0,0,8)});header.Children.Add(new TextBlock{Text=group=="未分组"?"选择后会移回未分组。":"添加后保留原有分组；全部视图只显示一次。",Foreground=Brushes.LightGray,Margin=new Thickness(0,0,0,10)});var query=new TextBox{MinHeight=38,ToolTip="搜索已有软件",Margin=new Thickness(0,0,0,12)};header.Children.Add(query);var footer=new WrapPanel();DockPanel.SetDock(footer,System.Windows.Controls.Dock.Bottom);root.Children.Add(footer);var list=new ListBox{Margin=new Thickness(0,0,0,12)};root.Children.Add(list);var candidates=Prefs.Apps.Where(a=>!FeatureRules.InGroup(a,group)).ToList();var selected=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Action fill=()=>{list.Items.Clear();foreach(var a in candidates.Where(a=>LayoutRules.Matches(a.Name,query.Text.Trim()))){var entry=a;var check=new CheckBox{Content=entry.Name+"  ·  "+string.Join(" / ",FeatureRules.Memberships(entry)),IsChecked=selected.Contains(entry.Path),Margin=new Thickness(7),ToolTip=entry.Path};check.Checked+=(ss,ee)=>selected.Add(entry.Path);check.Unchecked+=(ss,ee)=>selected.Remove(entry.Path);list.Items.Add(check);}};query.TextChanged+=(ss,ee)=>fill();footer.Children.Add(FeatureUi.Button("全选结果",()=>{foreach(var a in candidates.Where(a=>LayoutRules.Matches(a.Name,query.Text.Trim())))selected.Add(a.Path);fill();}));footer.Children.Add(FeatureUi.Button("取消全选",()=>{selected.Clear();fill();}));footer.Children.Add(FeatureUi.Button("添加到本组",()=>{var before=BeginBoardEdit();int count=FeatureRules.AddShared(Prefs,selected,group);EndBoardEdit(before,"添加已有图标");Refresh();Board.ClearSearch();Board.SetStatus("已添加 "+count+" 个已有图标到「"+group+"」");w.Close();}));footer.Children.Add(FeatureUi.Button("关闭",()=>w.Close()));fill();w.ShowDialog();}finally{Board.ModalBusy=previous;}}
        public void AutoGroupApps(Window owner=null){var before=BeginBoardEdit();AutoGroupRules.ReloadCatalog();foreach(var entry in Prefs.Apps.Where(a=>FeatureRules.GroupName(a)=="未分组"))LaunchInfoService.Enrich(entry);int count=AutoGroupRules.ApplyUnassigned(Prefs);EndBoardEdit(before,"自动分组");Refresh();int remaining=Prefs.Apps.Count(a=>FeatureRules.GroupName(a)=="未分组");MessageBox.Show(owner??OwnerWindow,"已自动分组 "+count+" 个软件。\n还有 "+remaining+" 个未识别，可手动移动到分组。已有手动分组已保留。","GlassBoard");}
        public void ManageGroups(Window owner=null){Board.ClearDragState();bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var w=FeatureUi.Dialog("软件分组",owner??OwnerWindow,520,450);var root=new DockPanel{Margin=new Thickness(22)};w.Content=root;var row=new WrapPanel();DockPanel.SetDock(row,System.Windows.Controls.Dock.Bottom);root.Children.Add(row);var list=new ListBox{Margin=new Thickness(0,0,0,14)};root.Children.Add(list);Action reload=()=>{string selected=list.SelectedItem as string;list.ItemsSource=null;list.ItemsSource=Prefs.Groups.ToList();if(selected!=null)list.SelectedItem=selected;};reload();
            row.Children.Add(FeatureUi.Button("新增",()=>{string name=FeatureUi.Ask(w,"新分组名称");if(name==null)return;if(name=="全部"||name=="未分组"||name.Length>32||Prefs.Groups.Any(g=>g.Equals(name,StringComparison.CurrentCultureIgnoreCase))){MessageBox.Show(w,"名称重复、过长或属于内置分类。");return;}var before=BeginBoardEdit();Prefs.Groups.Add(name);EndBoardEdit(before,"新增分组");Refresh();reload();}));
            row.Children.Add(FeatureUi.Button("改名",()=>{string old=list.SelectedItem as string;if(old==null)return;string name=FeatureUi.Ask(w,"分组改名",old);if(name==null)return;try{if(name.Length>32)throw new ArgumentException("名称最多 32 个字");var before=BeginBoardEdit();FeatureRules.RenameGroup(Prefs,old,name);EndBoardEdit(before,"重命名分组");Refresh();reload();}catch(Exception ex){MessageBox.Show(w,ex.Message);}}));
            row.Children.Add(FeatureUi.Button("删除分组",()=>{string name=list.SelectedItem as string;if(name==null)return;if(MessageBox.Show(w,"删除分组「"+name+"」？入口保留并移到未分组。","GlassBoard",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;var before=BeginBoardEdit();FeatureRules.DeleteGroup(Prefs,name);EndBoardEdit(before,"删除分组");Refresh();reload();}));w.ShowDialog();
        }finally{Board.ModalBusy=previous;}}
        public void ManageWorkspaces(Window owner=null){bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var w=FeatureUi.Dialog("工作区 · 一次打开一组工具",owner??OwnerWindow,780,640);var root=new Grid{Margin=new Thickness(22)};w.Content=root;root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition());root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
            var header=new StackPanel();root.Children.Add(header);header.Children.Add(new TextBlock{Text="把应用、素材文件夹和项目文件组成一个工作区",FontSize=17,Margin=new Thickness(0,0,0,8)});var name=new TextBox{Text="创作工作区",MinHeight=38,Margin=new Thickness(0,0,0,12)};header.Children.Add(name);
            var body=new Grid();body.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(190)});body.ColumnDefinitions.Add(new ColumnDefinition());Grid.SetRow(body,1);root.Children.Add(body);var saved=new ListBox{Margin=new Thickness(0,0,12,12),DisplayMemberPath="Name"};body.Children.Add(saved);var choices=new ListBox{Margin=new Thickness(0,0,0,12)};Grid.SetColumn(choices,1);body.Children.Add(choices);var picked=new Dictionary<string,CheckBox>(StringComparer.OrdinalIgnoreCase);Workspace current=null;
            Action<IEnumerable<string>> fill=paths=>{var set=new HashSet<string>(paths,StringComparer.OrdinalIgnoreCase);choices.Items.Clear();picked.Clear();var apps=Prefs.Apps.Concat(set.Where(path=>!Prefs.Apps.Any(a=>a.Path.Equals(path,StringComparison.OrdinalIgnoreCase))).Select(path=>new Entry{Name=System.IO.Path.GetFileNameWithoutExtension(path),Path=path})).ToList();foreach(var app in apps){var check=new CheckBox{Content=app.Name,ToolTip=app.Path,IsChecked=set.Contains(app.Path),Margin=new Thickness(5)};picked[app.Path]=check;choices.Items.Add(check);}};
            Action reload=()=>{saved.ItemsSource=null;saved.ItemsSource=Prefs.Workspaces.ToList();};reload();fill(new string[0]);saved.SelectionChanged+=(s,e)=>{current=saved.SelectedItem as Workspace;if(current!=null){name.Text=current.Name;fill(current.Paths);}};
            var row=new WrapPanel();Grid.SetRow(row,2);root.Children.Add(row);row.Children.Add(FeatureUi.Button("新建",()=>{saved.SelectedItem=null;current=null;name.Text="新工作区";fill(new string[0]);}));row.Children.Add(FeatureUi.Button("全选",()=>{foreach(var item in picked.Values)item.IsChecked=true;}));row.Children.Add(FeatureUi.Button("取消全选",()=>{foreach(var item in picked.Values)item.IsChecked=false;}));
            row.Children.Add(FeatureUi.Button("保存工作区",()=>{string title=name.Text.Trim();var paths=picked.Where(x=>x.Value.IsChecked==true).Select(x=>x.Key).ToList();if(title.Length==0||paths.Count==0){MessageBox.Show(w,"填写名称并勾选至少一个入口。");return;}if(Prefs.Workspaces.Any(x=>x!=current&&x.Name.Equals(title,StringComparison.CurrentCultureIgnoreCase))){MessageBox.Show(w,"工作区名称已存在。");return;}if(current==null){current=new Workspace();Prefs.Workspaces.Add(current);}current.Name=title;current.Paths=paths;Save();RefreshTrayMenu();var savedWork=current;reload();saved.SelectedItem=savedWork;}));
            row.Children.Add(FeatureUi.Button("打开已选",()=>{var work=new Workspace{Name=name.Text,Paths=picked.Where(x=>x.Value.IsChecked==true).Select(x=>x.Key).ToList()};w.Close();LaunchWorkspace(work);}));row.Children.Add(FeatureUi.Button("删除工作区",()=>{if(current==null)return;Prefs.Workspaces.Remove(current);current=null;Save();RefreshTrayMenu();reload();fill(new string[0]);}));w.ShowDialog();
        }finally{Board.ModalBusy=previous;}}
        public async void LaunchWorkspace(Workspace work){work.Normalize();Board.CollapseSmooth();RunningWindows.Scan();var failures=new List<string>();foreach(var path in work.Paths){if(Application.Current==null||Application.Current.Dispatcher.HasShutdownStarted)return;try{var entry=Prefs.Apps.FirstOrDefault(a=>a.Path.Equals(path,StringComparison.OrdinalIgnoreCase))??new Entry{Path=path,Name=System.IO.Path.GetFileNameWithoutExtension(path)};if(!RunningWindows.IsRunning(entry))Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch{failures.Add(System.IO.Path.GetFileName(path));}await Task.Delay(150);}if(failures.Count>0)MessageBox.Show("这些入口无法打开：\n"+string.Join("\n",failures),work.Name);}
        public bool ManageSchemes(Window owner=null){bool applied=false;bool previous=Board.ModalBusy;Board.ModalBusy=true;try{var w=FeatureUi.Dialog("外观方案",owner??OwnerWindow,650,480);var root=new DockPanel{Margin=new Thickness(22)};w.Content=root;var heading=new TextBlock{Text="保存配色、尺寸、位置、图标和应用布局；切换保留后来新增的入口。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(heading,System.Windows.Controls.Dock.Top);root.Children.Add(heading);var row=new WrapPanel();DockPanel.SetDock(row,System.Windows.Controls.Dock.Bottom);root.Children.Add(row);var list=new ListBox{Margin=new Thickness(0,0,0,14),DisplayMemberPath="Name"};root.Children.Add(list);var files=new Dictionary<AppearanceScheme,string>();
            Action reload=()=>{files.Clear();foreach(string path in SchemeStore.Files())try{var scheme=SchemeStore.Load(path);files[scheme]=path;}catch{}list.ItemsSource=null;list.ItemsSource=files.Keys.OrderBy(s=>s.Name).ToList();};reload();
            row.Children.Add(FeatureUi.Button("保存当前",()=>{string name=FeatureUi.Ask(w,"方案名称");if(name==null)return;var scheme=FeatureRules.Capture(Prefs,name);SchemeStore.Embed(scheme);SchemeStore.Save(scheme,System.IO.Path.Combine(SchemeStore.Folder,Guid.NewGuid().ToString("N")+".json"));reload();}));
            row.Children.Add(FeatureUi.Button("应用方案",()=>{var selected=list.SelectedItem as AppearanceScheme;if(selected==null)return;try{var scheme=SchemeStore.Load(files[selected]);SchemeStore.Materialize(scheme);FeatureRules.Apply(Prefs,scheme);editHistory.Clear();applied=true;Refresh();RefreshTrayMenu();Board.Hide();w.Close();}catch(Exception ex){MessageBox.Show(w,ex.Message,"无法应用方案");}}));
            row.Children.Add(FeatureUi.Button("导出",()=>{var scheme=list.SelectedItem as AppearanceScheme;if(scheme==null)return;var pick=new Microsoft.Win32.SaveFileDialog{FileName="GlassBoard_外观方案.json",Filter="外观方案|*.json"};if(pick.ShowDialog(w)==true)File.Copy(files[scheme],pick.FileName,true);}));
            row.Children.Add(FeatureUi.Button("导入",()=>{var pick=new Microsoft.Win32.OpenFileDialog{Filter="外观方案|*.json"};if(pick.ShowDialog(w)!=true)return;try{var scheme=SchemeStore.Load(pick.FileName);SchemeStore.Save(scheme,System.IO.Path.Combine(SchemeStore.Folder,Guid.NewGuid().ToString("N")+".json"));reload();}catch(Exception ex){MessageBox.Show(w,ex.Message,"无法导入方案");}}));
            row.Children.Add(FeatureUi.Button("删除方案",()=>{var scheme=list.SelectedItem as AppearanceScheme;if(scheme==null)return;if(MessageBox.Show(w,"删除保存的方案？当前外观保持。","GlassBoard",MessageBoxButton.YesNo)==MessageBoxResult.Yes){File.Delete(files[scheme]);reload();}}));w.ShowDialog();
        }finally{Board.ModalBusy=previous;}if(applied&&settingsWindow!=null&&owner!=settingsWindow)settingsWindow.Close();return applied;}
    }
}
